"use client";

import Link from "next/link";
import { useAuth } from "@/contexts/AuthContext";
import { LogOut, Wallet } from "lucide-react";

export default function Navbar() {
  const { user, userData, logout } = useAuth();

  return (
    <header className="sticky top-0 z-40 bg-white border-b border-slate-100 shadow-sm">
      <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
        <Link href="/" className="flex items-center gap-2">
          <span className="bg-blue-600 text-white font-black px-3 py-1.5 rounded-xl text-lg">
            DoKhai
          </span>
          <span className="font-extrabold text-xl text-slate-800">Shop</span>
        </Link>

        <div className="flex items-center gap-3">
          {user ? (
            <div className="flex items-center gap-2">
              <Link
                href="/wallet"
                className="bg-blue-50 text-blue-600 font-bold px-3 py-1.5 rounded-xl text-xs sm:text-sm border border-blue-100"
              >
                {(userData?.wallet || 0).toLocaleString("vi-VN")}đ
              </Link>
              <button
                onClick={logout}
                className="p-2 text-slate-400 hover:text-rose-500 rounded-lg transition"
                title="Đăng xuất"
              >
                <LogOut className="w-5 h-5" />
              </button>
            </div>
          ) : (
            <Link
              href="/auth/login"
              className="bg-blue-600 hover:bg-blue-700 text-white font-bold text-sm px-4 py-2 rounded-xl transition"
            >
              Đăng nhập
            </Link>
          )}
        </div>
      </div>
    </header>
  );
}