"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { Home, Gamepad2, Wallet, ShoppingBag, User } from "lucide-react";

export default function BottomNav() {
  const pathname = usePathname();

  const navItems = [
    { name: "Home", href: "/", icon: Home },
    { name: "Game", href: "/product", icon: Gamepad2 },
    { name: "Nạp", href: "/wallet", icon: Wallet },
    { name: "Giỏ", href: "/cart", icon: ShoppingBag },
    { name: "Tài khoản", href: "/wallet", icon: User },
  ];

  return (
    <nav className="md:hidden fixed bottom-0 left-0 right-0 z-[999999] bg-white border-t border-slate-200 shadow-[0_-4px_20px_rgba(0,0,0,0.1)] px-2 pt-2 pb-[max(0.75rem,env(safe-area-inset-bottom))]">
      <div className="grid grid-cols-5 gap-1 max-w-md mx-auto">
        {navItems.map((item) => {
          const isActive = pathname === item.href;
          return (
            <Link
              key={item.name}
              href={item.href}
              className={`flex flex-col items-center justify-center py-1.5 px-1 rounded-xl transition-colors touch-manipulation select-none active:bg-slate-100 ${
                isActive
                  ? "text-blue-600 font-bold bg-blue-50"
                  : "text-slate-500 hover:text-slate-800"
              }`}
            >
              <item.icon className={`w-5 h-5 ${isActive ? "text-blue-600" : "text-slate-500"}`} />
              <span className="text-[10px] mt-1 truncate">{item.name}</span>
            </Link>
          );
        })}
      </div>
    </nav>
  );
}